#!/usr/bin/env python3
"""Writes the AUR PKGBUILD and .SRCINFO for a release. Run by the release
workflow:

    render.py VERSION SHA_SOURCE
"""

import pathlib
import sys

REPO = "NathanielInman/roundhouse"
DESC = "One lamp in your bar; the whole machine slides out of it"
ROOT = pathlib.Path(__file__).resolve().parent.parent


def main() -> None:
    version, src = sys.argv[1:3]

    pkgbuild = f'''# Maintainer: Nathaniel Inman <nate@theoestudio.com>
# Generated by packaging/render.py on release.
pkgname=roundhouse
pkgver={version}
pkgrel=1
pkgdesc="{DESC}"
arch=('x86_64' 'aarch64')
url="https://github.com/{REPO}"
license=('MIT')
depends=('gtk4' 'gtk4-layer-shell' 'gcc-libs' 'glibc' 'hwdata')
optdepends=('nvidia-utils: NVIDIA GPU readings through NVML'
            'pipewire: quantum, DSP load and dropouts on the Machine tab'
            'waybar: the bar the lamp lives in')
makedepends=('cargo')
source=("$pkgname-$pkgver.tar.gz::$url/archive/v$pkgver.tar.gz")
sha256sums=('{src}')

prepare() {{
  cd "$pkgname-$pkgver"
  export RUSTUP_TOOLCHAIN=stable
  cargo fetch --locked --target "$(rustc -vV | sed -n 's/host: //p')"
}}

build() {{
  cd "$pkgname-$pkgver"
  export RUSTUP_TOOLCHAIN=stable
  export CARGO_TARGET_DIR=target
  cargo build --frozen --release -p rh -p rh-board
}}

check() {{
  cd "$pkgname-$pkgver"
  export RUSTUP_TOOLCHAIN=stable
  cargo test --frozen -p rh-core
}}

package() {{
  cd "$pkgname-$pkgver"
  install -Dm755 target/release/rh "$pkgdir/usr/bin/rh"
  install -Dm755 target/release/rh-board "$pkgdir/usr/bin/rh-board"
  sed 's|@BINDIR@|/usr/bin|' packaging/systemd/roundhouse.service > "$srcdir/roundhouse.service"
  install -Dm644 "$srcdir/roundhouse.service" "$pkgdir/usr/lib/systemd/user/roundhouse.service"
  install -Dm644 LICENSE "$pkgdir/usr/share/licenses/$pkgname/LICENSE"
  install -Dm644 README.md "$pkgdir/usr/share/doc/$pkgname/README.md"
  install -Dm644 docs/design.md "$pkgdir/usr/share/doc/$pkgname/design.md"
}}
'''

    srcinfo = f'''pkgbase = roundhouse
\tpkgdesc = {DESC}
\tpkgver = {version}
\tpkgrel = 1
\turl = https://github.com/{REPO}
\tarch = x86_64
\tarch = aarch64
\tlicense = MIT
\tmakedepends = cargo
\tdepends = gtk4
\tdepends = gtk4-layer-shell
\tdepends = gcc-libs
\tdepends = glibc
\tdepends = hwdata
\toptdepends = nvidia-utils: NVIDIA GPU readings through NVML
\toptdepends = pipewire: quantum, DSP load and dropouts on the Machine tab
\toptdepends = waybar: the bar the lamp lives in
\tsource = roundhouse-{version}.tar.gz::https://github.com/{REPO}/archive/v{version}.tar.gz
\tsha256sums = {src}

pkgname = roundhouse
'''
    aur = ROOT / "packaging" / "aur"
    aur.mkdir(parents=True, exist_ok=True)
    (aur / "PKGBUILD").write_text(pkgbuild)
    (aur / ".SRCINFO").write_text(srcinfo)


if __name__ == "__main__":
    main()
